blocks.text:
.row {
  display: flex;
  gap: 16px;
  align-items: center;
  justify-content: space-between;
}

:root {
  --bg: #ffffff;
  --text: #0b1b33;
}
@media (prefers-color-scheme: dark) {
  :root {
    --bg: #050b1a;
    --text: #e8f1ff;
  }
}
body { background: var(--bg); color: var(--text); }
